
CREATE TABLE students (
    id INT AUTO_INCREMENT PRIMARY KEY,
    applying_grade VARCHAR(50) NOT NULL,
    selected_stream VARCHAR(50),
    curriculum_board VARCHAR(50) NOT NULL,
    first_name VARCHAR(50) NOT NULL,
    middle_name VARCHAR(50),
    last_name VARCHAR(50) NOT NULL,
    dob DATE NOT NULL,
    gender VARCHAR(20) NOT NULL,
    blood_group VARCHAR(10),
    prev_school VARCHAR(100),
    prev_grade_score VARCHAR(50),
    father_name VARCHAR(100) NOT NULL,
    mother_name VARCHAR(100) NOT NULL,
    primary_phone VARCHAR(15) NOT NULL,
    guardian_email VARCHAR(100) NOT NULL,
    residential_address TEXT NOT NULL,
    city VARCHAR(50) NOT NULL,
    state VARCHAR(50) NOT NULL,
    pincode VARCHAR(10) NOT NULL,
    transport_facility BOOLEAN DEFAULT FALSE,
    student_photo VARCHAR(255),
    birth_certificate VARCHAR(255),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
desc students;
ALTER TABLE students 
MODIFY COLUMN student_photo LONGBLOB,
MODIFY COLUMN birth_certificate LONGBLOB;

alter table students add column status varchar(40) after pincode;
alter table students modify column status varchar(40) default 'Active';
update students set status="Passed Out";
 
